    facts: { de: ["2.544 m hoch.", "Kreis Arge?.", "Gletschermorphologie."], hu: ["2544 m magas.", "Arge? megyében.", "Jégkori formák."], ro: ["2.544 m altitudine.", "În jude?ul Arge?.", "Relief glaciar."], en: ["Altitude 2,544 m.", "In Arge? County.", "Glacial morphology."] },
