    facts: { de: ["Scari?oara-Eishöhle.", "Motzen-Land (?ara Mo?ilor).", "Bihor-Gipfel 1.849 m."], hu: ["Szkerisórai Jégbarlang.", "Mócvidék (?ara Mo?ilor).", "Bihari-csúcs 1849 m."], ro: ["Ghe?arul Scari?oara.", "?ara Mo?ilor.", "Vf. Bihor 1.849 m."], en: ["Scari?oara Ice Cave.", "Motzen Land (?ara Mo?ilor).", "Bihor Peak 1,849 m."] },
